{
  "up": "Select DISTINCT molecule_dictionary.chembl_id AS chembl_id, molecule_dictionary.pref_name AS pref_name, compound_structures.canonical_smiles AS canonical_smiles, drug_indication.mesh_id AS indication_curie, drug_indication.mesh_heading AS indication_label, drug_indication.max_phase_for_ind AS max_phase_for_ind FROM molecule_dictionary JOIN drug_indication ON molecule_dictionary.molregno = drug_indication.molregno LEFT JOIN compound_structures ON molecule_dictionary.molregno = compound_structures.molregno WHERE drug_indication.max_phase_for_ind = 4 AND drug_indication.mesh_id IS NOT NULL AND drug_indication.mesh_heading IS NOT NULL AND molecule_dictionary.therapeutic_flag = 1"
}
